def _diagnostic_contract(language: str, root_type: str, source: bytes, diagnostics: list[dict[str, Any]]) -> dict[str, Any]:
    """Classify unresolved parser diagnostics as complete, local, or unusable."""
    total_lines = max(1, source.count(b"\n") + 1)
    total_bytes = len(source)
    affected_lines = _union_size(
        [(int(item["start_line"]) - 1, int(item["end_line"])) for item in diagnostics]
    )
    affected_bytes = _union_size(
        [(int(item.get("start_byte", 0)), int(item.get("end_byte", 0))) for item in diagnostics]
    )
    coverage = {
        "diagnostic_count": len(diagnostics),
        "affected_lines": affected_lines,
        "total_lines": total_lines,
        "line_ratio": round(affected_lines / total_lines, 6),
        "affected_bytes": affected_bytes,
        "total_bytes": total_bytes,
        "byte_ratio": round(affected_bytes / max(1, total_bytes), 6),
    }
    reasons: list[str] = []
    if diagnostics and language not in {"c", "cpp"}:
        reasons.append("language-does-not-allow-local-syntax-degradation")
    if diagnostics and (root_type == "ERROR" or any(item.get("category") == "root-error" for item in diagnostics)):
        reasons.append("root-node-unusable")
    if len(diagnostics) > LOCAL_SYNTAX_MAX_DIAGNOSTICS:
        reasons.append("diagnostic-count-exceeds-local-limit")
    if coverage["line_ratio"] > LOCAL_SYNTAX_MAX_LINE_RATIO:
        reasons.append("line-coverage-exceeds-local-limit")
    if coverage["byte_ratio"] > LOCAL_SYNTAX_MAX_BYTE_RATIO:
        reasons.append("byte-coverage-exceeds-local-limit")
    outcome = "complete" if not diagnostics else ("unusable" if reasons else "partial")
    return {
        "outcome": outcome,
        "blocking": outcome == "unusable",
        "coverage": coverage,
        "unusable_reasons": reasons,
        "thresholds": {
            "max_diagnostic_count": LOCAL_SYNTAX_MAX_DIAGNOSTICS,
            "max_line_ratio": LOCAL_SYNTAX_MAX_LINE_RATIO,
            "max_byte_ratio": LOCAL_SYNTAX_MAX_BYTE_RATIO,
        },
    }

def _diagnostic_overlaps(entity: dict[str, Any], diagnostic: dict[str, Any]) -> bool:
    entity_start = int(entity["range"]["start_byte"])
    entity_end = int(entity["range"]["end_byte"])
    start = int(diagnostic.get("start_byte", 0))
    end = int(diagnostic.get("end_byte", start))
    if start == end:
        return entity_start <= start <= entity_end
    return entity_start < end and start < entity_end

def syntax_warning_id(
    repository: dict[str, Any],
    file_entry: dict[str, Any],
    diagnostics: list[dict[str, Any]],
) -> str:
    """Build the commit-sensitive ID shared by fresh and exact-blob parses."""
    return stable_id(
        "syntax-warning",
        repository["commit"],
        file_entry["blob"],
        file_entry["path"],
        *(
            value
            for diagnostic in diagnostics
            for value in (
                diagnostic.get("category"),
                diagnostic.get("start_byte"),
                diagnostic.get("end_byte"),
            )
        ),
    )

def merge_csharp_partials(repository: dict[str, Any], entities: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Merge partial C# type declarations into one logical entity with audited fragments."""
    type_kinds = {"class", "struct", "record", "interface"}
    groups: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for entity in entities:
        if entity.get("language") == "csharp" and entity.get("kind") in type_kinds and entity.get("is_partial"):
            groups.setdefault((entity["kind"], entity["qualified_name"]), []).append(entity)
    replacements: dict[str, str] = {}
    merged_by_old: dict[str, dict[str, Any]] = {}
    removed: set[str] = set()
    for (kind, qualified), values in sorted(groups.items()):
        if len(values) < 2:
            continue
        ordered = sorted(values, key=lambda item: (item["path"], item["range"]["start_byte"], item["id"]))
        primary = sorted(
            ordered,
            key=lambda item: (
                -sum(1 for child in entities if child.get("parent_id") == item["id"] and child.get("page_eligible")),
                item["path"],
                item["range"]["start_byte"],
                item["id"],
            ),
        )[0]
        logical_id = stable_id("ent", repository["commit"], "csharp-partial", kind, qualified)
        logical = dict(primary)
        logical["id"] = logical_id
        logical["partial"] = True
        logical["fragments"] = [
            {
                "fragment_id": value["id"],
                "path": value["path"],
                "blob": value["blob"],
                "range": value["range"],
            }
            for value in ordered
        ]
        logical["classification_evidence"] = sorted(set(logical.get("classification_evidence", []) + ["partial-logical-entity"]))
        for value in ordered:
            replacements[value["id"]] = logical_id
            merged_by_old[value["id"]] = logical
            removed.add(value["id"])
    if not replacements:
        return entities
    result: list[dict[str, Any]] = []
    emitted: set[str] = set()
    for entity in entities:
        if entity["id"] in removed:
            logical = merged_by_old[entity["id"]]
            if logical["id"] not in emitted:
                result.append(logical)
                emitted.add(logical["id"])
            continue
        value = dict(entity)
        if value.get("parent_id") in replacements:
            value["parent_id"] = replacements[value["parent_id"]]
        result.append(value)
    return result

def lexical_links(entities: list[dict[str, Any]], sources: dict[str, bytes]) -> list[dict[str, Any]]:
    by_name: dict[str, list[dict[str, Any]]] = {}
    for entity in entities:
        if entity["kind"] != "file" and len(entity["name"]) >= 2:
            by_name.setdefault(entity["name"], []).append(entity)
    links: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for source_entity in entities:
        if source_entity["kind"] == "file":
            continue
        data = sources.get(source_entity["path"], b"")
        region = data[source_entity["range"]["start_byte"] : source_entity["range"]["end_byte"]].decode("utf-8", errors="replace")
        referenced_names = set(re.findall(r"[A-Za-z_$][A-Za-z0-9_$]*", region))
        for name in sorted(referenced_names.intersection(by_name)):
            targets = by_name[name]
            if name == source_entity["name"]:
                continue
            if len(targets) != 1:
                continue
            target = targets[0]
            if target["id"] == source_entity["id"]:
                continue
            key = (source_entity["id"], target["id"], "references")
            if key in seen:
                continue
            seen.add(key)
            links.append({
                "id": stable_id("link", *key),
                "type": "references",
                "source": source_entity["id"],
                "target": target["id"],
                "provider": "tree-sitter-lexical-candidate",
                "evidence": {"name": name, "source_path": source_entity["path"]},
            })
    for entity in entities:
        if entity["parent_id"]:
            key = (entity["parent_id"], entity["id"], "contains")
            links.append({
                "id": stable_id("link", *key),
                "type": "contains",
                "source": entity["parent_id"],
                "target": entity["id"],
                "provider": "tree-sitter",
                "evidence": {"path": entity["path"], "range": entity["range"]},
            })
    return links

def _replace_output_prefix(value: Any, old_output: str, new_output: str) -> Any:
    """Rewrite only serialized paths that point inside a relocated output."""

    if isinstance(value, dict):
        return {key: _replace_output_prefix(item, old_output, new_output) for key, item in value.items()}
    if isinstance(value, list):
        return [_replace_output_prefix(item, old_output, new_output) for item in value]
    if not isinstance(value, str):
        return value
    updated = value.replace(old_output, new_output)
    old_posix = old_output.replace("\\", "/")
    new_posix = new_output.replace("\\", "/")
    updated = updated.replace(old_posix, new_posix)
    return updated.replace(quote(old_output, safe=""), quote(new_output, safe=""))

def _load_state(output: Path) -> dict[str, Any]:
    path = output / "state.json"
    if not path.is_file():
        raise CkbError(f"state.json does not exist: {path}")
    state = json_load(path)
    if "parse_batches" not in state and "chunks" in state:
        state["parse_batches"] = state["chunks"]
    # Keep the former chunk key as a CLI/state compatibility alias.  Both keys
    # reference the same in-memory list and are serialized together.
    state["chunks"] = state["parse_batches"]
    state = _relocate_completed_output(output, state)
    if isinstance(state.get("source_snapshot"), dict):
        assert_source_snapshot(state["repository"], state["source_snapshot"])
    else:
        # Compatibility for completed 3.2.0 outputs created before fixed
        # source snapshots existed.
        assert_unchanged(state["repository"])
    record = state.get("page_config")
    if not isinstance(record, dict):
        raise StaleSourceError("output has no pinned page configuration; initialize it with the current Skill version")
    config_path = output / str(record.get("relative_path", "page-config.json"))
    if not config_path.is_file():
        raise StaleSourceError(f"pinned page configuration is missing: {config_path}")
    actual_hash = sha256_file(config_path)
    if actual_hash != record.get("sha256"):
        raise StaleSourceError(
            f"pinned page configuration drifted: expected {record.get('sha256')}, got {actual_hash}"
        )
    try:
        config = normalize_page_config(json_load(config_path))
    except CkbError as exc:
        raise StaleSourceError(f"pinned page configuration is invalid: {exc}") from exc
    if page_config_bytes(config) != config_path.read_bytes():
        raise StaleSourceError("pinned page configuration is not in canonical normalized form")
    return state

def _parse_entry(value: str) -> tuple[str | None, str | None, str]:
    if "#" not in value:
        return None, None, value
    left, qualified = value.split("#", 1)
    if ":" not in left:
        raise CkbError(f"entry must use LANGUAGE:PATH#QUALIFIED_NAME: {value}")
    language, path = left.split(":", 1)
    return language, path.replace("\\", "/"), qualified

def _expand_entries(
    all_entities: list[dict[str, Any]],
    links: list[dict[str, Any]],
    entry_ids: list[str],
    depth: int,
    direction: str,
) -> set[str]:
    if not entry_ids:
        return set()
    outgoing: dict[str, set[str]] = defaultdict(set)
    incoming: dict[str, set[str]] = defaultdict(set)
    for link in links:
        if link["type"] != "references":
            continue
        outgoing[link["source"]].add(link["target"])
        incoming[link["target"]].add(link["source"])
    reached = set(entry_ids)
    frontier = deque((value, 0) for value in entry_ids)
    while frontier:
        current, level = frontier.popleft()
        if level >= depth:
            continue
        neighbors: set[str] = set()
        if direction in {"both", "callees"}:
            neighbors.update(outgoing.get(current, set()))
        if direction in {"both", "callers"}:
            neighbors.update(incoming.get(current, set()))
        for neighbor in neighbors:
            if neighbor not in reached:
                reached.add(neighbor)
                frontier.append((neighbor, level + 1))
    return reached

def _normalize_repo_selector(repo: Path, value: str) -> str:
    candidate = Path(value)
    resolved = candidate.resolve() if candidate.is_absolute() else (repo / candidate).resolve()
    if not path_inside(resolved, repo):
        raise CkbError(f"C# project selector is outside the repository: {value}")
    return resolved.relative_to(repo).as_posix()

def _resolve_csharp_workspace(
    repository: dict[str, Any],
    project_files: list[dict[str, Any]],
    csharp_solution: str | None,
    csharp_project: str | None,
) -> dict[str, Any]:
    if csharp_solution and csharp_project:
        raise CkbError("use only one of --csharp-solution or --csharp-project")
    repo = Path(repository["root"]).resolve()
    tracked = {item["path"]: item for item in project_files}
    solutions = sorted(path for path in tracked if PurePosixPath(path).suffix.lower() in {".sln", ".slnx"})
    projects = sorted(path for path in tracked if PurePosixPath(path).suffix.lower() == ".csproj")
    selected: str | None = None
    kind = "folder"
    selection = "fallback-no-project-file"
    if csharp_solution:
        selected = _normalize_repo_selector(repo, csharp_solution)
        if selected not in solutions:
            raise CkbError(f"--csharp-solution is not a tracked .sln/.slnx file: {selected}; candidates={solutions}")
        kind, selection = "solution", "explicit"
    elif csharp_project:
        selected = _normalize_repo_selector(repo, csharp_project)
        if selected not in projects:
            raise CkbError(f"--csharp-project is not a tracked .csproj file: {selected}; candidates={projects}")
        kind, selection = "project", "explicit"
    elif len(solutions) == 1:
        selected, kind, selection = solutions[0], "solution", "unique-auto"
    elif len(solutions) > 1:
        raise CkbError(f"multiple tracked C# solutions require --csharp-solution: candidates={solutions}")
    elif len(projects) == 1:
        selected, kind, selection = projects[0], "project", "unique-auto"
    elif len(projects) > 1:
        raise CkbError(f"multiple tracked C# projects require --csharp-project: candidates={projects}")
    return {
        "kind": kind,
        "path": selected,
        "selection": selection,
        "solution_candidates": solutions,
        "project_candidates": projects,
        "workspace_root": str(repo),
        "precision": "exact" if selected else "bounded-approximate",
        "restore": {"requested": False, "performed": False, "network_restore": False},
    }

def _rekey_reused_file_parse(
    repository: dict[str, Any],
    file_entry: dict[str, Any],
    previous: dict[str, Any],
) -> dict[str, Any]:
    """Reuse an exact-blob parse while rebuilding every commit-sensitive ID."""
    old_file = previous.get("file", {})
    if old_file.get("path") != file_entry.get("path") or old_file.get("blob") != file_entry.get("blob"):
        raise CkbError(f"migration parse reuse mismatch: {file_entry.get('path')}")
    if previous.get("parse", {}).get("status") != "passed":
        raise CkbError(f"migration source parse did not pass: {file_entry.get('path')}")
    id_map: dict[str, str] = {}
    for entity in previous.get("entities", []):
        if entity.get("kind") == "file":
            new_id = file_entry["id"]
        else:
            source_range = entity.get("range", {})
            new_id = stable_id(
                "ent",
                repository["commit"],
                file_entry["blob"],
                file_entry["path"],
                source_range.get("start_byte"),
                source_range.get("end_byte"),
                entity.get("kind"),
                entity.get("name"),
            )
        id_map[str(entity["id"])] = new_id
    parse_record = json.loads(json.dumps(previous["parse"]))
    warning_id_map: dict[str, str] = {}
    for warning in parse_record.get("warnings", []):
        old_warning_id = str(warning.get("id") or "")
        if not old_warning_id:
            raise CkbError(f"migration source syntax warning has no ID: {file_entry.get('path')}")
        new_warning_id = syntax_warning_id(repository, file_entry, parse_record.get("diagnostics", []))
        warning_id_map[old_warning_id] = new_warning_id
        warning["id"] = new_warning_id
        warning["file"] = file_entry["path"]
        old_affected = [str(value) for value in warning.get("affected_entity_ids", [])]
        missing_affected = sorted(value for value in old_affected if value not in id_map)
        if missing_affected:
            raise CkbError(
                f"migration source syntax warning references unknown entities: {file_entry.get('path')} {missing_affected}"
            )
        warning["affected_entity_ids"] = [id_map[value] for value in old_affected]
    entities: list[dict[str, Any]] = []
    for entity in previous.get("entities", []):
        item = json.loads(json.dumps(entity))
        item["id"] = id_map[str(entity["id"])]
        item["commit"] = repository["commit"]
        item["blob"] = file_entry["blob"]
        item["path"] = file_entry["path"]
        if entity.get("parent_id"):
            item["parent_id"] = id_map[str(entity["parent_id"])]
        old_warning_ids = [str(value) for value in entity.get("syntax_warning_ids", [])]
        missing_warning_ids = sorted(value for value in old_warning_ids if value not in warning_id_map)
        if missing_warning_ids:
            raise CkbError(
                f"migration source entity references unknown syntax warnings: {file_entry.get('path')} {missing_warning_ids}"
            )
        item["syntax_warning_ids"] = [warning_id_map[value] for value in old_warning_ids]
        entities.append(item)
    return {
        "file": dict(file_entry),
        "parse": parse_record,
        "entities": entities,
        "migration_reuse": {
            "basis": "exact-path-language-blob-and-passed-parse",
            "previous_file_id": old_file.get("id"),
            "rekeyed_entity_count": len(entities),
            "rekeyed_syntax_warning_count": len(warning_id_map),
        },
    }

def _semantic_warning_summary(warnings: list[dict[str, Any]]) -> dict[str, Any]:
    unique: dict[tuple[str, str, str], dict[str, Any]] = {}
    for warning in warnings:
        key = (str(warning.get("kind")), str(warning.get("language")), str(warning.get("file")))
        unique[key] = {
            "kind": warning.get("kind"),
            "language": warning.get("language"),
            "file": warning.get("file"),
            "precision": warning.get("precision"),
            "build_evidence": warning.get("build_evidence", {}),
            "absence_inference_allowed": bool(warning.get("absence_inference_allowed", False)),
        }
    ordered = [unique[key] for key in sorted(unique)]
    return {
        "status": "warning" if ordered else "complete",
        "warning_count": len(ordered),
        "warnings": ordered[:8],
        "omitted_warning_count": max(0, len(ordered) - 8),
    }
